root.command:

IF OBJECT_ID(N'dbo.WooCommerceSettingsTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.WooCommerceSettingsTbl', N'ImportAutoPullMode') IS NOT NULL
   AND NOT EXISTS (
       SELECT 1
       FROM sys.extended_properties ep
       WHERE ep.major_id = OBJECT_ID(N'dbo.WooCommerceSettingsTbl')
         AND ep.minor_id = 0
         AND ep.name = N'MigrateAutoPullSinceSync_v1')
BEGIN
    UPDATE dbo.WooCommerceSettingsTbl
    SET ImportAutoPullMode = N'SinceLastSync'
    WHERE SettingsID = 1
      AND ImportAutoPullMode = N'Today';

    EXEC sys.sp_addextendedproperty
        @name = N'MigrateAutoPullSinceSync_v1',
        @value = N'1',
        @level0type = N'SCHEMA', @level0name = N'dbo',
        @level1type = N'TABLE',  @level1name = N'WooCommerceSettingsTbl';
END
